#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[])
{
    // If there are not enough arguments, show usage
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    // Parse the shift amount (may have a leading '+' or '-')
    long raw_shift = strtol(argv[1], NULL, 10);

    // Reduce the shift to the range 0‑25 (the original program does this
    // with a custom modulo‑26 calculation).
    int shift = (int)raw_shift;
    shift = ((shift % 26) + 26) % 26;   // always non‑negative

    const char *src = argv[2];

    for (size_t i = 0; src[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (c >= 'A' && c <= 'Z') {
            // Upper‑case letter
            putchar(((c - 'A' + shift) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            // Lower‑case letter
            putchar(((c - 'a' + shift) % 26) + 'a');
        } else {
            // Non‑alphabetic characters are passed through unchanged
            putchar(c);
        }
    }

    return 0;
}
